import { Component, h, Prop, Event, EventEmitter, Element, State, Watch, Host } from '@stencil/core';
import { CheckboxGroupContext, CheckboxGroupContextValue } from './context';
import { FormBaseComponent } from '@src/components/ks-form/FormBaseComponent';
import { FormContextValueReconcile } from '@src/components/ks-form/utils';
import { CheckboxGroupValue, CheckboxValue } from './types';
import { Uncontrollable, Vue2ValueFix } from '@src/framework/decorators';
import { Provide } from '@src/framework/runtime-context';
import { formatCSSLength } from '@src/shared/dom';
import { Orientation } from '@src/shared/base-props';
import { generateUniqueId } from '@src/shared/unclassified/unique-id';

const prefix = 'checkbox-group';

/**
 * @slot default - Checkbox items rendered inside the checkbox group.
 * @part base - The base container of the component.
 */
@Component({
  tag: 'ks-checkbox-group',
  styleUrl: 'index.scss',
  shadow: true,
})
export class KsCheckboxGroup extends FormBaseComponent<CheckboxGroupValue> {
  protected static vModel = { prop: 'value', event: 'ksChange' };
  @Element() el!: HTMLKsCheckboxGroupElement;

  @Provide({
    context: CheckboxGroupContext,
  })
  private checkboxGroupContext: CheckboxGroupContextValue = {
    htmlName: '',
    disabled: undefined,
    value: undefined,
    onValueChange: (value: CheckboxValue) => {
      if (this.internalValueState?.includes(value)) {
        this.internalValueState = this.internalValueState.filter((item) => item !== value);
      } else {
        this.internalValueState = [...(this.internalValueState || []), value].sort();
      }
    },
  };

  /** The name attribute of the checkbox inside the group. */
  @Prop() htmlName = generateUniqueId();
  /** Determine whether all checkboxes in the group are disabled. When set to `true`, none of the checkboxes can be interacted with by the user. */
  @Prop() @FormContextValueReconcile() disabled?: boolean;
  /** An array of values representing the currently selected checkboxes in the group. This array contains the values of the checkboxes that are checked by the user. */
  @Prop() @Vue2ValueFix() @FormContextValueReconcile() value?: CheckboxGroupValue;
  /** An array of values that sets the initial selected state of the checkboxes when the component is first rendered. This value does not change after the initial render. */
  @Prop() defaultValue?: CheckboxGroupValue;
  @Uncontrollable('value', 'defaultValue', 'ksChange') @State() internalValueState?: CheckboxGroupValue;
  /** Controls whether the checkboxes are laid out horizontally or vertically. Use `horizontal` for inline rows and `vertical` for stacked lists. */
  @Prop() orientation: Orientation = 'horizontal';

  /** The gap between checkboxes in the group. */
  @Prop() gap?: string | number;

  /** Custom event triggered when the selected values in the checkbox group change. It returns the new array of selected values, allowing the parent component to react to the changes. */
  @Event({ bubbles: false, composed: false }) ksChange?: EventEmitter<CheckboxGroupValue>;

  // eslint-disable-next-line @typescript-eslint/no-useless-constructor
  constructor() {
    super();
  }

  @Watch('htmlName')
  @Watch('disabled')
  @Watch('internalValueState')
  handleContextValueChange() {
    this.checkboxGroupContext = {
      ...this.checkboxGroupContext,
      htmlName: this.htmlName,
      disabled: this.disabled,
      value: this.internalValueState,
    };
  }

  componentWillLoad() {
    this.handleContextValueChange();
  }

  render() {
    return (
      <Host class="KsCheckboxGroup">
        <div
          class={{
            [`${prefix}`]: true,
            [`${prefix}--${this.orientation}`]: true,
          }}
          style={{
            gap: formatCSSLength(this.gap),
          }}
          part="base"
        >
          <slot></slot>
        </div>
      </Host>
    );
  }
}
